56	void ThreadEngineBarrier::acquire()
57	{
58	    forever {
59	        int localCount = count.loadRelaxed();
60	        if (localCount < 0) {
61	            if (count.testAndSetOrdered(localCount, localCount -1))
62	                return;
63	        } else {
64	            if (count.testAndSetOrdered(localCount, localCount + 1))
65	                return;
66	        }
67	        qYieldCpu();
68	    }
69	}
