72	{
73	    forever {
74	        int localCount = count.loadRelaxed();
75	        if (localCount == -1) {
76	            if (count.testAndSetOrdered(-1, 0)) {
77	                semaphore.release();
78	                return 0;
79	            }
80	        } else if (localCount < 0) {
81	            if (count.testAndSetOrdered(localCount, localCount + 1))
82	                return qAbs(localCount + 1);
83	        } else {
84	            if (count.testAndSetOrdered(localCount, localCount - 1))
85	                return localCount - 1;
86	        }
87	        qYieldCpu();
88	    }
89	}
