93	{
94	    forever {
95	        int localCount = count.loadRelaxed();
96	        if (localCount == 0)
97	            return;
98	
99	        Q_ASSERT(localCount > 0); // multiple waiters are not allowed.
100	        if (count.testAndSetOrdered(localCount, -localCount)) {
101	            semaphore.acquire();
102	            return;
103	        }
